solution.solution.cpp:
#include <cmath>
#include <cstdint>
#include <utility>

class FixedStep
{
public:
    FixedStep(std::int64_t step, int maxSteps) : step_{ step }, maxSteps_{ maxSteps } {}

    int advance(std::int64_t elapsed)
    {
        if (elapsed > 0) accumulator_ += elapsed;
        std::int64_t due{ accumulator_ / step_ };
        accumulator_ -= due * step_;
        if (due > maxSteps_)
        {
            dropped_ += (due - maxSteps_) * step_;
            due = maxSteps_;
        }
        ticks_ += due;
        return static_cast<int>(due);
    }

    double alpha() const { return static_cast<double>(accumulator_) / static_cast<double>(step_); }
    std::int64_t ticks() const { return ticks_; }
    std::int64_t dropped() const { return dropped_; }

private:
    std::int64_t step_;
    int maxSteps_;
    std::int64_t accumulator_{ 0 };
    std::int64_t ticks_{ 0 };
    std::int64_t dropped_{ 0 };
};

std::pair<float, float> clampMove(float x, float y)
{
    if (!std::isfinite(x) || !std::isfinite(y)) return { 0.0f, 0.0f };
    const float length{ std::sqrt(x * x + y * y) };
    if (length <= 1.0f) return { x, y };
    return { x / length, y / length };
}

unitTests:
#include <limits>
TEST("running whole steps") {
    FixedStep s{ 16000, 5 };
    CHECK_EQ(s.advance(10000), 0);
    CHECK_NEAR(s.alpha(), 0.625, 1e-12);
    CHECK_EQ(s.advance(10000), 1);
    CHECK_NEAR(s.alpha(), 0.25, 1e-12);
    CHECK_EQ(s.advance(48000), 3);
    CHECK_NEAR(s.alpha(), 0.25, 1e-12);
    CHECK_EQ(s.ticks(), 4);
    CHECK_EQ(s.advance(-500), 0);
    CHECK_EQ(s.advance(12000), 1);
    CHECK_NEAR(s.alpha(), 0.0, 1e-12);
}
TEST("not spiralling after a long pause") {
    FixedStep s{ 16000, 5 };
    s.advance(4000);
    CHECK_EQ(s.advance(1000000), 5);
    CHECK_EQ(s.dropped(), 57 * 16000);
    CHECK_NEAR(s.alpha(), 0.75, 1e-12);
    CHECK_EQ(s.ticks(), 5);
    CHECK_EQ(s.advance(4000), 1);
}
TEST("clamping movement") {
    const auto a{ clampMove(3, 4) };
    CHECK_NEAR(a.first, 0.6, 1e-6); CHECK_NEAR(a.second, 0.8, 1e-6);
    const auto b{ clampMove(0.5f, -0.25f) };
    CHECK_NEAR(b.first, 0.5, 1e-9); CHECK_NEAR(b.second, -0.25, 1e-9);
    const auto c{ clampMove(1, 1) };
    CHECK_NEAR(c.first, 0.70710678, 1e-6); CHECK_NEAR(c.second, 0.70710678, 1e-6);
    const auto d{ clampMove(std::numeric_limits<float>::quiet_NaN(), 0) };
    CHECK(d.first == 0 && d.second == 0);
    const auto e{ clampMove(1, std::numeric_limits<float>::infinity()) };
    CHECK(e.first == 0 && e.second == 0);
    const auto f{ clampMove(-1, 0) };
    CHECK(f.first == -1 && f.second == 0);
}

